CREATE TABLE `core_file_info` (
  `fjid` int NOT NULL AUTO_INCREMENT COMMENT '附件id',
  `fjdz` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '附件地址',
  `gyslxdh` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '供应商联系电话',
  `ddlx` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单类型',
  `fjmc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '附件名称',
  `lrrydm` int DEFAULT NULL COMMENT '录入人员代码',
  `lrsj` datetime DEFAULT NULL COMMENT '录入时间',
  `xgrydm` int DEFAULT NULL COMMENT '修改人员代码',
  `xgsj` datetime DEFAULT NULL COMMENT '修改时间',
  `yxbz` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '有效标志（1有效、0无效）',
  PRIMARY KEY (`fjid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='附件信息表';
