--
-- Table structure for table `material_inbound`
--

DROP TABLE IF EXISTS `material_inbound`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `material_inbound` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `project_id` int DEFAULT NULL COMMENT '关联项目ID',
  `batch_number` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次号',
  `batch_sub_number` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次分号',
  `material_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '材料名称',
  `material_spec` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `material_unit` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `supplier_id` int DEFAULT NULL COMMENT '供应商ID',
  `inbound_quantity` decimal(18,2) DEFAULT NULL COMMENT '入库量',
  `inbound_price` decimal(18,2) DEFAULT NULL COMMENT '入库单价',
  `inbound_total_amount` decimal(18,2) DEFAULT NULL COMMENT '入库合价',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '状态: pending(拟入库), completed(已入库)',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  `invoice_id` int DEFAULT NULL COMMENT '关联发票ID',
