--
-- Table structure for table `ums_order`
--

DROP TABLE IF EXISTS `ums_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ums_order` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `order_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单编号',
  `material_name` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料名称',
  `project_id` int DEFAULT NULL COMMENT '项目ID',
  `supplier_id` int DEFAULT NULL COMMENT '供应商ID',
  `supplier_contact_person` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商联系人',
  `contact_phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `cutting_time` date DEFAULT NULL COMMENT '下料时间',
  `estimated_arrival_time` date DEFAULT NULL COMMENT '预计到场时间',
  `material_details` text COLLATE utf8mb4_unicode_ci COMMENT '材料明细',
  `order_amount` decimal(18,2) DEFAULT NULL COMMENT '订单金额',
  `material_manager` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料负责人',
  `sub_project_manager` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分项目负责人',
  `attachments` text COLLATE utf8mb4_unicode_ci COMMENT '附件',
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `fjid` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  KEY `project_id` (`project_id`),
  KEY `supplier_id` (`supplier_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

