  `fjid` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `pay_number` (`pay_number`),
  KEY `order_id` (`order_id`),
  KEY `payer_supplier_id` (`payer_supplier_id`),
