  CONSTRAINT `ums_pay_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `ums_order` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ums_pay_ibfk_2` FOREIGN KEY (`payer_supplier_id`) REFERENCES `ums_payer` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ums_pay_ibfk_3` FOREIGN KEY (`payee_supplier_id`) REFERENCES `ums_supplier` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=54354 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
