/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ums_payer` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `type_id` int NOT NULL COMMENT '付款单位类型(1:单位, 2:个人)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '付款单位名称',
  `bank_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户行',
  `account_number` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账号',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

