--
-- Table structure for table `ums_project`
--

DROP TABLE IF EXISTS `ums_project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ums_project` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `project_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `project_full_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目全称',
  `project_scale` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目规模',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `project_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目状态',
  `project_amount` decimal(18,2) DEFAULT NULL COMMENT '项目金额',
  `attachments` text COLLATE utf8mb4_unicode_ci COMMENT '附件',
  `create_at` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=204 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

