--
-- Table structure for table `ums_rights`
--

DROP TABLE IF EXISTS `ums_rights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ums_rights` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限名称',
  `code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权限标识',
  `type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权限类型',
  `url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路径地址',
  `icon_sign` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标',
  `status` tinyint(1) DEFAULT NULL COMMENT '是否开启',
  `sort` int DEFAULT NULL,
  `open_type` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打开方式',
  `pid` int DEFAULT NULL COMMENT '父类编号',
  PRIMARY KEY (`id`),
  KEY `pid` (`pid`),
  CONSTRAINT `ums_rights_ibfk_1` FOREIGN KEY (`pid`) REFERENCES `ums_rights` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

